def fixed(value, places)
  scale = 10**places
  format("%d.%0#{places}d", value / scale, value % scale)
def pct(a, b)
  fixed(10000 * a / b, 2)
    when 'GC'
      table = s.chars.tally
      emit(*BASES.each_char.map { |b| "#{b}=#{table.fetch(b, 0)}" }, "GC=#{pct(gc(s), n)}%")
    when 'GCWINDOW'
      0.step(n - width, step) { |i| emit("#{i + 1}-#{i + width}", pct(gc(s[i, width]), width) + '%') }
